import React, { useState } from "react";
import { HiChevronLeft, HiChevronRight, HiX } from "react-icons/hi";

const ImageCarousel = ({ image, allImages, setIsRendered }) => {
  const [currentIndex, setCurrentIndex] = useState(image.index ?? 0);

  const prevPhoto = () => {
    const nextImg = currentIndex === 0 ? allImages.length - 1 : currentIndex - 1;
    setCurrentIndex(nextImg);
  };

  const nextPhoto = () => {
    const prevImg = currentIndex === allImages.length - 1 ? 0 : currentIndex + 1;
    setCurrentIndex(prevImg);
  };

  return (
    <div id="img-container" className="mt-10 rounded-[2rem] border border-white/10 bg-black/70 p-3 shadow-glow sm:p-5">
      <div className="relative overflow-hidden rounded-[1.5rem]">
        <img
          src={allImages[currentIndex].img}
          alt={`${allImages[currentIndex].type} view`}
          className="h-[70vh] w-full object-cover"
        />

        <button
          type="button"
          onClick={() => setIsRendered(false)}
          className="absolute right-4 top-4 rounded-full border border-white/20 bg-black/40 p-2 text-white backdrop-blur"
          aria-label="Close gallery view"
        >
          <HiX size={22} />
        </button>

        <div className="absolute inset-x-0 bottom-0 flex items-end justify-between bg-gradient-to-t from-black/90 via-black/30 to-transparent p-6 sm:p-8">
          <div>
            <p className="text-xs uppercase tracking-[0.35em] text-amber-300">Featured view</p>
            <h3 className="mt-2 text-xl font-semibold text-white">{allImages[currentIndex].type}</h3>
          </div>
          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={prevPhoto}
              className="rounded-full border border-white/20 bg-white/10 p-2 text-white backdrop-blur"
              aria-label="Previous image"
            >
              <HiChevronLeft size={22} />
            </button>
            <button
              type="button"
              onClick={nextPhoto}
              className="rounded-full border border-white/20 bg-white/10 p-2 text-white backdrop-blur"
              aria-label="Next image"
            >
              <HiChevronRight size={22} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ImageCarousel;
